import { withEve } from "eve/vercel";

/**
 * Service graph for one Vercel project:
 *
 * - `frontend`: Next.js, serves every public path not claimed below.
 * - `backend`: FastAPI, public under `/api/*`. The frontend also reaches it over the
 *   `BACKEND_URL` service binding.
 * - `eve`: the agent in `agent/`, generated by `withEve` and mounted at `/eve/v1/*`.
 *   That route is public, but the channel auth in `agent/channels/eve.ts` only admits
 *   Vercel OIDC tokens from this project (and local dev), so only the backend can call it.
 */
export default await withEve({
  services: {
    frontend: {
      root: "frontend/",
      devCommand:
        "pnpx smee-client --url https://smee.io/N7jUBl7FOcUpeB --target http://localhost:$PORT/codebases/upload & next dev --port $PORT",
      bindings: [
        {
          type: "service",
          service: "backend",
          format: "url",
          env: "BACKEND_URL",
        },
      ],
    },
    backend: {
      root: "backend/",
      entrypoint: "app.main:app",
    },
  },
  routes: [
    { src: "^/api/(.*)$", destination: { type: "service", service: "backend" } },
    { src: "^(.*)$", destination: { type: "service", service: "frontend" } },
  ],
});
